<section id="product-preview" aria-labelledby="preview-heading" class="min-w-0 scroll-mt-28">
    <div class="mb-4 flex flex-wrap items-center justify-between gap-2">
        <h2 id="preview-heading" class="text-sm font-semibold text-slate-700">A clearer view of your operations</h2>
        <span class="rounded border border-amber-200 bg-amber-50 px-2 py-1 text-xs font-medium text-amber-900">Illustrative preview</span>
    </div>
    <div class="overflow-hidden rounded-xl border border-slate-300 bg-white shadow-xl shadow-slate-900/10">
        <div class="flex items-center justify-between gap-3 border-b border-slate-200 bg-slate-100 px-4 py-3">
            <span class="text-sm font-semibold tracking-tight">GoErion <span class="font-normal text-slate-500">/ Workspace</span></span>
            <span aria-hidden="true" class="flex gap-1.5"><span class="size-2 rounded-full bg-slate-300"></span><span class="size-2 rounded-full bg-slate-300"></span><span class="size-2 rounded-full bg-slate-300"></span></span>
        </div>
        <div class="flex min-w-0">
            <aside aria-label="Example application sidebar" class="hidden w-32 shrink-0 border-r border-slate-800 bg-slate-900 px-3 py-5 text-xs text-slate-300 sm:block lg:hidden xl:block">
                <p class="mb-5 px-2 text-xs font-semibold tracking-wider text-slate-400">WORKSPACE</p>
                <ul class="grid gap-2"><li class="rounded bg-white/10 px-2 py-2 text-white">Overview</li><li class="px-2 py-2">Products</li><li class="px-2 py-2">Inventory</li><li class="px-2 py-2">Purchasing</li><li class="px-2 py-2">Sales</li><li class="mt-5 border-t border-slate-700 px-2 pt-4">Company access</li></ul>
            </aside>
            <div class="min-w-0 flex-1 p-4 sm:p-5">
                <p class="text-xs font-medium text-slate-500">Example company · Main branch</p>
                <h3 class="mt-2 text-xl font-semibold tracking-tight">Inventory overview</h3>
                <p class="mt-1 text-xs leading-5 text-slate-500">Main warehouse · Sample product records</p>
                <div class="my-5 grid grid-cols-2 gap-3">
                    <div class="rounded-lg border border-slate-200 p-3"><p class="text-xs text-slate-500">Stock visibility</p><p class="mt-2 text-sm font-semibold">By warehouse</p></div>
                    <div class="rounded-lg border border-amber-200 bg-amber-50 p-3"><p class="text-xs text-amber-900">Replenishment</p><p class="mt-2 text-sm font-semibold text-amber-950">Review low stock</p></div>
                </div>
                <table class="w-full table-fixed text-left text-xs leading-5">
                    <caption class="sr-only">Illustrative inventory, not live business data</caption>
                    <thead class="border-y border-slate-200 bg-slate-50 text-slate-500"><tr><th scope="col" class="w-1/2 px-2 py-2 font-medium">Product</th><th scope="col" class="px-1 py-2 font-medium">Unit</th><th scope="col" class="px-1 py-2 font-medium">Status</th></tr></thead>
                    <tbody class="divide-y divide-slate-100 text-slate-700">
                        <tr><th scope="row" class="px-2 py-4 font-medium">Hex bolts <span class="block font-normal text-slate-500">M10 × 50 mm</span></th><td class="px-1">Box</td><td class="px-1">In stock</td></tr>
                        <tr><th scope="row" class="px-2 py-4 font-medium">Cement <span class="block font-normal text-slate-500">50 kg bag</span></th><td class="px-1">Bag</td><td class="px-1 font-medium text-amber-900">Low stock</td></tr>
                        <tr><th scope="row" class="px-2 py-4 font-medium">PVC pipe <span class="block font-normal text-slate-500">25 mm</span></th><td class="px-1">Length</td><td class="px-1">In stock</td></tr>
                    </tbody>
                </table>
                <div class="mt-4 flex flex-wrap justify-between gap-2 rounded-md bg-slate-100 px-3 py-3 text-xs"><span class="font-medium">Purchase order</span><span class="text-slate-600">Awaiting receipt</span></div>
            </div>
        </div>
    </div>
    <p class="mt-4 text-xs leading-5 text-slate-500">Example interface with sample data. No live company information is shown.</p>
